"""Built-in metrics.
"""
from __future__ import absolute_import
from __future__ import division
from __future__ import print_function

import six
from . import backend as K
from .losses import mean_squared_error
from .losses import mean_absolute_error
from .losses import mean_absolute_percentage_error
from .losses import mean_squared_logarithmic_error
from .losses import hinge
from .losses import logcosh
from .losses import squared_hinge
from .losses import categorical_crossentropy
from .losses import sparse_categorical_crossentropy
from .losses import binary_crossentropy
from .losses import kullback_leibler_divergence
from .losses import poisson
from .losses import cosine_proximity
from .utils.generic_utils import deserialize_keras_object
from .utils.generic_utils import serialize_keras_object


def binary_accuracy(y_true, y_pred):
    rounded_preds = K.round(y_pred)
    equality = K.equal(y_true, rounded_preds)
    return K.mean(equality, axis=-1)


def categorical_accuracy(y_true, y_pred):
    true_argmax = K.argmax(y_true, axis=-1)
    pred_argmax = K.argmax(y_pred, axis=-1)
    matches = K.equal(true_argmax, pred_argmax)
    return K.cast(matches, K.floatx())


def sparse_categorical_accuracy(y_true, y_pred):
    true_max = K.max(y_true, axis=-1)
    pred_argmax = K.cast(K.argmax(y_pred, axis=-1), K.floatx())
    matches = K.equal(true_max, pred_argmax)
    return K.cast(matches, K.floatx())


def top_k_categorical_accuracy(y_true, y_pred, k=5):
    labels = K.argmax(y_true, axis=-1)
    in_top = K.in_top_k(y_pred, labels, k)
    return K.mean(in_top, axis=-1)


def sparse_top_k_categorical_accuracy(y_true, y_pred, k=5):
    labels = K.cast(K.max(y_true, axis=-1), 'int32')
    in_top = K.in_top_k(y_pred, labels, k)
    return K.mean(in_top, axis=-1)


# Aliases

mse = MSE = mean_squared_error
mae = MAE = mean_absolute_error
mape = MAPE = mean_absolute_percentage_error
msle = MSLE = mean_squared_logarithmic_error
cosine = cosine_proximity


def serialize(metric_fn):
    return serialize_keras_object(metric_fn)


def deserialize(config, custom_objects=None):
    return deserialize_keras_object(config,
                                    module_objects=globals(),
                                    custom_objects=custom_objects,
                                    printable_module_name='metric function')


def get(identifier):
    if isinstance(identifier, dict):
        cfg = {'class_name': str(identifier), 'config': {}}
        return deserialize(cfg)
    elif isinstance(identifier, six.string_types):
        name = str(identifier)
        return deserialize(name)
    elif callable(identifier):
        return identifier
    else:
        raise ValueError('Could not interpret '
                         'metric function identifier:', identifier)
